          "hi": "अंजलि से पूछा गया: 'क्या तापमान लोहे पर जंग लगने की दर को प्रभावित करता है?' पहले वह लिखती: 'हाँ, गर्मी में जंग जल्दी लगती है।' CER से उसने लिखा: [दावा] उच्च तापमान जंग की गति बढ़ाता है। [प्रमाण] प्रयोगशाला में $40^\\circ\\text{C}$ पर 7 दिनों में 3.5g जंग बनी, जबकि $10^\\circ\\text{C}$ पर केवल 1.1g। [तर्क] उच्च तापमान से कणों की ऊर्जा बढ़ती है जिससे रासायनिक प्रतिक्रिया तेज होती है।",
