          "hi": "इंटरनेट पर कोई भी बिना जांचे कुछ भी लिख सकता है। CRAAP टेस्ट 5 पैमानों पर जानकारी को परखता है: Currency (क्या यह ताज़ा है?), Relevance (क्या यह आपके काम की है?), Authority (लेखक/संस्था कौन है?), Accuracy (क्या तथ्य प्रमाणित हैं?), Purpose (क्या यह सिखाने के लिए है या सामान बेचने के लिए?)।",
